            CudaAsm.Emit("mov.f32 %0, o10;", out float v2);
            CudaAsm.Emit("mov.f32 %0, o11;", out float v3);
            TaStore(q, outp, p, t0, cnt, h, rowA, 16 + 2 * t4, v0 * iA, v1 * iA);
            TaStore(q, outp, p, t0, cnt, h, rowB, 16 + 2 * t4, v2 * iB, v3 * iB);
        }
        if (nOut > 3)
        {
            CudaAsm.Emit("mov.f32 %0, o12;", out float v0);
            CudaAsm.Emit("mov.f32 %0, o13;", out float v1);
            CudaAsm.Emit("mov.f32 %0, o14;", out float v2);
            CudaAsm.Emit("mov.f32 %0, o15;", out float v3);
            TaStore(q, outp, p, t0, cnt, h, rowA, 24 + 2 * t4, v0 * iA, v1 * iA);
            TaStore(q, outp, p, t0, cnt, h, rowB, 24 + 2 * t4, v2 * iB, v3 * iB);
        }
        if (nOut > 4)
        {
            CudaAsm.Emit("mov.f32 %0, o16;", out float v0);
            CudaAsm.Emit("mov.f32 %0, o17;", out float v1);
            CudaAsm.Emit("mov.f32 %0, o18;", out float v2);
            CudaAsm.Emit("mov.f32 %0, o19;", out float v3);
            TaStore(q, outp, p, t0, cnt, h, rowA, 32 + 2 * t4, v0 * iA, v1 * iA);
            TaStore(q, outp, p, t0, cnt, h, rowB, 32 + 2 * t4, v2 * iB, v3 * iB);
        }
        if (nOut > 5)
        {
            CudaAsm.Emit("mov.f32 %0, o20;", out float v0);
            CudaAsm.Emit("mov.f32 %0, o21;", out float v1);
            CudaAsm.Emit("mov.f32 %0, o22;", out float v2);
            CudaAsm.Emit("mov.f32 %0, o23;", out float v3);
            TaStore(q, outp, p, t0, cnt, h, rowA, 40 + 2 * t4, v0 * iA, v1 * iA);
            TaStore(q, outp, p, t0, cnt, h, rowB, 40 + 2 * t4, v2 * iB, v3 * iB);
        }
        if (nOut > 6)
        {
            CudaAsm.Emit("mov.f32 %0, o24;", out float v0);
            CudaAsm.Emit("mov.f32 %0, o25;", out float v1);
            CudaAsm.Emit("mov.f32 %0, o26;", out float v2);
            CudaAsm.Emit("mov.f32 %0, o27;", out float v3);
            TaStore(q, outp, p, t0, cnt, h, rowA, 48 + 2 * t4, v0 * iA, v1 * iA);
            TaStore(q, outp, p, t0, cnt, h, rowB, 48 + 2 * t4, v2 * iB, v3 * iB);
        }
        if (nOut > 7)
        {
            CudaAsm.Emit("mov.f32 %0, o28;", out float v0);
            CudaAsm.Emit("mov.f32 %0, o29;", out float v1);
            CudaAsm.Emit("mov.f32 %0, o30;", out float v2);
            CudaAsm.Emit("mov.f32 %0, o31;", out float v3);
            TaStore(q, outp, p, t0, cnt, h, rowA, 56 + 2 * t4, v0 * iA, v1 * iA);
            TaStore(q, outp, p, t0, cnt, h, rowB, 56 + 2 * t4, v2 * iB, v3 * iB);
        }
    }


    private static float Fa2Mask(float s, int pos, int start, int end, float softCap)
    {
        if (pos < start || pos > end) return float.NegativeInfinity;
        return softCap > 0 ? Tanh(s / softCap) * softCap : s;
    }

    /// <summary>Two floats as an fp16x2 register (lo in the low half), the A-operand element order of mma.</summary>
    private static uint Fa2Pack(float lo, float hi)
    {
        CudaAsm.Emit("cvt.rn.f16x2.f32 %0, %1, %2;", out uint packed, hi, lo);
        return packed;
    }
